import React from 'react';
import Nav from "../nav/nav";
import './home.css'
import hatAndNameLogo from "../../img/hatAndNameLogo.png"

const Home = () => {
    return (
        <div className="home">
            <Nav></Nav>
            <img src={hatAndNameLogo} alt="hat and chefcito logo"/>
            <p className="slogan">Cooking Made Simple & Fun! Discover easy, delicious recipes for every meal of the day, designed with your
                busy life in mind.</p>
        </div>
    );
};

export default Home;
